CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, passhash TEXT NOT NULL, salt TEXT NOT NULL, language TEXT DEFAULT 'Persian', avatar TEXT DEFAULT 'female', created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes (id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL, name TEXT NOT NULL, year INTEGER NOT NULL, term TEXT NOT NULL, code TEXT UNIQUE NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enrollments (class_id TEXT NOT NULL, student_id TEXT NOT NULL, PRIMARY KEY(class_id,student_id));
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY,class_id TEXT NOT NULL,filename TEXT NOT NULL,content TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY,class_id TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,questions TEXT NOT NULL,flashcards TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY,class_id TEXT NOT NULL,lesson_id TEXT,title TEXT NOT NULL,kind TEXT NOT NULL,questions TEXT NOT NULL,due TEXT,minutes INTEGER DEFAULT 30,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY,task_id TEXT NOT NULL,student_id TEXT NOT NULL,answers TEXT NOT NULL,score REAL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,class_id TEXT NOT NULL,title TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance (session_id TEXT NOT NULL,student_id TEXT NOT NULL,joined_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(session_id,student_id));
CREATE TABLE IF NOT EXISTS reflections (id TEXT PRIMARY KEY,class_id TEXT NOT NULL,student_id TEXT NOT NULL,learned TEXT NOT NULL,hard TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
